import{_ as o,o as d,c as p,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-MGET-Command.md","filePath":"manual-zh/Matrix-MGET-Command.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Matrix-MGET-Command.md"};function t(_,e,r,n,i,l){return d(),p("div",null,[...e[0]||(e[0]=[c('<h4 id="_16-4-11-mget-命令" tabindex="-1">16.4.11 <code>MGET</code> 命令 <a class="header-anchor" href="#_16-4-11-mget-命令" aria-label="Permalink to &quot;16.4.11 `MGET` 命令&quot;">​</a></h4><pre><code>MGET [/FILE=_file_]\n     [/TYPE={COV _|_ CORR _|_ MEAN _|_ STDDEV _|_ N _|_ COUNT}].\n</code></pre><p><code>MGET</code> 命令从矩阵文件（参见 <a href="./Matrix-Files">Matrix Files</a>）读取数据到矩阵变量中。</p><p><code>MGET</code> 的所有子命令都是可选的。在 <code>FILE</code> 子命令上指定要读取的矩阵文件的名称或句柄；如果省略，则命令读取活动文件。</p><p>默认情况下，<code>MGET</code> 读取矩阵文件中的全部数据。在 <code>TYPE</code> 上指定以空格分隔的矩阵类型列表，可将数据种类限制为指定的类型：</p><p><code>COV</code></p><p>协方差矩阵。</p><p><code>CORR</code></p><p>相关系数矩阵。</p><p><code>MEAN</code></p><p>均值向量。</p><p><code>STDDEV</code></p><p>标准差向量。</p><p><code>N</code></p><p>个案计数向量。</p><p><code>COUNT</code></p><p>计数向量。</p><p><code>MGET</code> 读取整个矩阵文件，并自动命名、创建和填充矩阵变量。它通过拼接以下内容来构造每个变量的名称：</p><ul><li>标识矩阵类型的 2 字符前缀：</li></ul><p><code>CV</code></p><p>协方差矩阵。</p><p><code>CR</code></p><p>相关系数矩阵。</p><p><code>MN</code></p><p>均值向量。</p><p><code>SD</code></p><p>标准差向量。</p><p><code>NC</code></p><p>个案计数向量。</p><p><code>CN</code></p><p>计数向量。</p><ul><li>如果矩阵文件有因子变量，则为 <code>F _n_</code>，其中 <em>n</em> 是标识一组因子的编号：第一组为 <code>F1</code>，第二组为 <code>F2</code>，依此类推。对于合并数据（因子都取系统缺失值），省略此部分。</li><li>如果矩阵文件有拆分文件变量，则为 <code>S _n_</code>，其中 <em>n</em> 是标识一个拆分组的编号：第一组为 <code>S1</code>，第二组为 <code>S2</code>，依此类推。</li></ul><p>如果 <code>MGET</code> 选择的名称与已有变量重名，它会发出警告且不改变该变量。</p>',33)])])}const s=o(a,[["render",t]]);export{T as __pageData,s as default};
